-- ② 서비스

@Service
class OrderService {
    private final Counter placed;
    private final Counter rejected;
    private final DistributionSummary amount;
    private final Timer timer;

    OrderService(MeterRegistry registry) {
        this.placed = Counter.builder("order.placed")
                .description("실제로 접수된 주문").register(registry);
        this.rejected = Counter.builder("order.rejected")
                .description("반려된 주문").register(registry);
        this.amount = DistributionSummary.builder("order.amount")
                .baseUnit("won").publishPercentiles(0.5, 0.95).register(registry);
        this.timer = Timer.builder("order.place").register(registry);
    }

    Result place(String item, int qty) {
        return timer.record(() -> {
            if (!stock.has(item, qty)) {
                Metrics.counter("order.rejected", "reason", "stock").increment();
                return Result.rejected("stock");
            }
            var o = repo.save(new Order(item, qty));   // 저장이 먼저다
            placed.increment();
            amount.record(o.getTotal());
            return Result.ok(o);
        });
    }
}

